    /**
     * Method to retrieve the Dependent via an DependentPrimaryKey.
     * @param 	id Long
     * @return 	Dependent
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Dependent handle( FindDependentQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getDependentId() );
    }
    
    /**
     * Method to retrieve a collection of all Dependents
     *
     * @param	query	FindAllDependentQuery 
     * @return 	List<Dependent> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Dependent> handle( FindAllDependentQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindDependent,
 * but only if the id matches
 *
 * @param		entity	Dependent
 */
	protected void emitFindDependent( Dependent entity ) {
		LOGGER.info("handling emitFindDependent" );
		
	    queryUpdateEmitter.emit(FindDependentQuery.class,
	                            query -> query.getFilter().getDependentId().equals(entity.getDependentId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllDependent
	 * 
	 * @param		entity	Dependent
	 */
	protected void emitFindAllDependent( Dependent entity ) {
		LOGGER.info("handling emitFindAllDependent" );
		
	    queryUpdateEmitter.emit(FindAllDependentQuery.class,
	                            query -> true,
	                            entity);
	}

	//--------------------------------------------------
